Rocq < 
Rocq < Record Lattice (A : Type) : Type := Build_Lattice
  { meet : A -> A -> A;
    join : A -> A -> A;
    top : A;
    bot : A;
    meet_commutative : forall a b : A, meet a b = meet b a;
    meet_associative : forall a b c : A,
                       meet (meet a b) c = meet a (meet b c);
    meet_absorptive : forall a b : A, meet a (join a b) = a;
    meet_idempotent : forall a : A, meet a a = a;
    join_commutative : forall a b : A, join a b = join b a;
    join_associative : forall a b c : A,
                       join (join a b) c = join a (join b c);
    join_absorptive : forall a b : A, join a (meet a b) = a;
    join_idempotent : forall a : A, join a a = a;
    meet_top : forall a : A, meet a top = a;
    meet_bot : forall a : A, meet a bot = bot;
    join_top : forall a : A, join a top = top;
    join_bot : forall a : A, join a bot = a;
    nontrivial : top <> bot }.

Arguments Lattice A%_type_scope
Arguments Build_Lattice A%_type_scope (meet join)%_function_scope 
  top bot
  (meet_commutative meet_associative meet_absorptive meet_idempotent
   join_commutative join_associative join_absorptive join_idempotent meet_top
   meet_bot join_top join_bot)%_function_scope
  nontrivial
Arguments meet {A}%_type_scope {Lattice} _ _
Arguments join {A}%_type_scope {Lattice} _ _
Arguments top {A}%_type_scope {Lattice}
Arguments bot {A}%_type_scope {Lattice}
Arguments meet_commutative {A}%_type_scope {Lattice} a b
Arguments meet_associative {A}%_type_scope {Lattice} a b c
Arguments meet_absorptive {A}%_type_scope {Lattice} a b
Arguments meet_idempotent {A}%_type_scope {Lattice} a
Arguments join_commutative {A}%_type_scope {Lattice} a b
Arguments join_associative {A}%_type_scope {Lattice} a b c
Arguments join_absorptive {A}%_type_scope {Lattice} a b
Arguments join_idempotent {A}%_type_scope {Lattice} a
Arguments meet_top {A}%_type_scope {Lattice} a
Arguments meet_bot {A}%_type_scope {Lattice} a
Arguments join_top {A}%_type_scope {Lattice} a
Arguments join_bot {A}%_type_scope {Lattice} a
Arguments nontrivial {A}%_type_scope {Lattice} _

Rocq <

